int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg) {
    int ret = 0;
    struct hiddev_usage *usage = NULL;
    int usage_length = 0;

    if (copy_from_user(&usage_length, user_arg, sizeof(int))) {
        return -EFAULT;
    }

    usage = kmalloc(sizeof(struct hiddev_usage) * usage_length, GFP_KERNEL);
    if (!usage) {
        return -ENOMEM;
    }

    if (copy_from_user(usage, user_arg, sizeof(struct hiddev_usage) * usage_length)) {
        kfree(usage);
        return -EFAULT;
    }

    switch (cmd) {
        case HIDIOCUSAGE_GET:
            for (int i = 0; i < usage_length; i++) {
                struct hid_report *report = hiddev->hid->find_report(hiddev->hid, usage[i].report_type, usage[i].report_id);
                if (!report) {
                    ret = -EINVAL;
                    break;
                }

                struct hid_field *field = report->field[usage[i].field_index];
                if (!field || usage[i].usage_index >= field->maxusage) {
                    ret = -EINVAL;
                    break;
                }

                usage[i].usage = field->usage[usage[i].usage_index];
                usage[i].value = field->value[usage[i].usage_index];
            }
            if (copy_to_user(user_arg, usage, sizeof(struct hiddev_usage) * usage_length)) {
                ret = -EFAULT;
            }
            break;
        case HIDIOCUSAGE_SET:
            for (int i = 0; i < usage_length; i++) {
                struct hid_report *report = hiddev->hid->find_report(hiddev->hid, usage[i].report_type, usage[i].report_id);
                if (!report) {
                    ret = -EINVAL;
                    break;
                }

                struct hid_field *field = report->field[usage[i].field_index];
                if (!field || usage[i].usage_index >= field->maxusage) {
                    ret = -EINVAL;
                    break;
                }

                field->value[usage[i].usage_index] = usage[i].value;
            }
            break;
        default:
            ret = -EINVAL;
            break;
    }

    kfree(usage);
    return ret;
}

int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg)
{
    struct hiddev_usage_ref *urefs;
    int ret = -EINVAL;
    int i, max;

    urefs = kmalloc_array(HIDDEV_MAX_USAGE, sizeof(struct hiddev_usage_ref), GFP_KERNEL);
