        if (!uref->usage)
            break;

        report = hiddev->hid->reports[uref->report_type];
        if (!report)
            break;

        field = report->field[uref->field_index];
        if (!field)
            break;

        if (uref->usage > field->maxusage) {
            ret = -EINVAL;
            break;
        }

        switch (cmd) {
        case HIDIOCUSAGEGET:
            uref->value = field->value[uref->usage];
            break;
        case HIDIOCUSAGESET:
            field->value[uref->usage] = uref->value;
            break;
