            ret = -EFAULT;
            break;
        }
    }

    kfree(urefs);
    return ret;
}

int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg) {
    int *usage_value;
    struct hid_report *report;
    struct hid_field *field;
    struct hid_usage *usage;
    int ret = 0;
    int i, j, usage_index;

    switch (cmd) {
        case HIDIOCGRUSAGE:
        case HIDIOCGRMAX:
        case HIDIOCGBUSAGE:
        case HIDIOCGBMAX:
        case HIDIOCGUVN:
        case HIDIOCGUVN: {
            if (get_user(usage_index, (int __user *)user_arg))
                return -EFAULT;

            if (usage_index < 0)
                return -EINVAL;

            report = hiddev->report;
            if (!report)
                return -ENODEV;

            field = report->field[0];
            if (!field)
                return -ENODEV;

            if (usage_index >= field->maxusage)
                return -EINVAL;

            usage = field->usage + usage_index;

            if (cmd == HIDIOCGRUSAGE || cmd == HIDIOCGBUSAGE) {
                usage_value = kmalloc(sizeof(int), GFP_KERNEL);
                if (!usage_value)
                    return -ENOMEM;

                *usage_value = usage->value;

                if (copy_to_user(user_arg, usage_value, sizeof(int))) {
                    kfree(usage_value);
                    return -EFAULT;
                }
                kfree(usage_value);
                return 0;
            } else if (cmd == HIDIOCGRMAX || cmd == HIDIOCGBMAX) {
                usage_value = kmalloc(sizeof(int), GFP_KERNEL);
                if (!usage_value)
                    return -ENOMEM;

                *usage_value = field->maxusage;

                if (copy_to_user(user_arg, usage_value, sizeof(int))) {
                    kfree(usage_value);
                    return -EFAULT;
                }
                kfree(usage_value);
                return 0;
            } else {
                return -EINVAL;
            }
        }
        case HIDIOCSUSAGE: {
            int value;

            if (copy_from_user(&value, user_arg, sizeof(int)))
                return -EFAULT;

            if (get_user(usage_index, (int __user *)user_arg))
                return -EFAULT;

            if (usage_index < 0)
                return -EINVAL;

            report = hiddev->report;
            if (!report)
                return -ENODEV;

            field = report->field[0];
            if (!field)
                return -ENODEV;

            if (usage_index >= field->maxusage)
                return -EINVAL;

            usage = field->usage + usage_index;
            usage->value = value;
            return 0;
        }
        default:
            return -EINVAL;
    }

    return ret;
}

int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg) {
    struct hiddev_usage_request *ureq;
    struct hid_report *report;
    struct hid_field *field;
    struct hid_usage *usage;
    int ret = 0;

    ureq = kmalloc(sizeof(*ureq), GFP_KERNEL);
    if (!ureq)
        return -ENOMEM;

    if (copy_from_user(ureq, user_arg, sizeof(*ureq))) {
        ret = -EFAULT;
        goto out;
    }

    report = hiddev->hid->report_descriptor;
    if (!report) {
        ret = -EINVAL;
        goto out;
    }

    switch (cmd) {
        case HIDIOCUSAGE:
            if (ureq->report_type < 0 || ureq->report_type >= HID_REPORT_TYPES) {
                ret = -EINVAL;
                goto out;
            }

            report = hiddev->hid->reports[ureq->report_type][ureq->report_id];
            if (!report) {
                ret = -EINVAL;
                goto out;
            }

            field = report->field[ureq->field_index];
            if (!field) {
                ret = -EINVAL;
                goto out;
            }

            usage = field->usage + ureq->usage_index;
            if (!usage || (usage - field->usage) >= field->maxusage) {
                ret = -EINVAL;
                goto out;
            }

            ureq->value = field->value[ureq->usage_index];

            if (copy_to_user(user_arg, ureq, sizeof(*ureq))) {
                ret = -EFAULT;
                goto out;
            }
            break;
        default:
            ret = -EINVAL;
            break;
    }

out:
    kfree(ureq);
    return ret;
}

int hiddev_ioctl_usage(struct hiddev *hiddev, unsigned int cmd, void __user *user_arg)
{
    struct hiddev_usage_ref *uref;
    struct hiddev_usage_ref *uref2;
    int ret = 0;
    int i, j;

    uref = kmalloc(sizeof(struct hiddev_usage_ref), GFP_KERNEL);
    if (!uref)
        return -ENOMEM;

    if (copy_from_user(uref, user_arg, sizeof(struct hiddev_usage_ref))) {
        ret = -EFAULT;
        goto out;
    }

    switch (cmd) {
    case HIDIOCUSAGE:
        uref2 = kmalloc(sizeof(struct hiddev_usage_ref) * uref->maxusage, GFP_KERNEL);
        if (!uref2) {
            ret = -ENOMEM;
            goto out;
        }

        if (copy_from_user(uref2, user_arg, uref->maxusage * sizeof(struct hiddev_usage_ref))) {
            kfree(uref2);
            ret = -EFAULT;
            goto out;
        }

        for (i = 0; i < uref->maxusage; i++) {
            if (uref2[i].usage > uref->usage_max || uref2[i].usage < uref->usage_min) {
                kfree(uref2);
                ret = -EINVAL;
                goto out;
            }
            uref->usage[i] = uref2[i].usage;
        }

        kfree(uref2);
        break;

    case HIDIOCGUSAGE:
        for (i = 0; i < uref->maxusage; i++) {
            uref->value[i] = hiddev->usage_value[i];
        }

        break;

    default:
        ret = -EINVAL;
        goto out;
    }

    if (copy_to_user(user_arg, uref, sizeof(struct hiddev_usage_ref))) {
        ret = -EFAULT;
        goto out;
    }

out:
    kfree(uref);
    return ret;
}
